let checkInterval = null;
let currentVersion = null;
let href = '';

// 获取当前页面版本（从主线程传入）
self.onmessage = function(e) {
  if (e.data.type === 'INIT') {
    currentVersion = e.data.version;
    href = (e.data.href || '') + '/version.json';
    startVersionCheck();
  } else if (e.data.type === 'STOP') {
    stopVersionCheck();
  }
};

// 开始版本检查
function startVersionCheck() {
  // 立即执行一次检查
  checkVersion();
  
  // 每分钟检查一次
  checkInterval = setInterval(checkVersion, 60 * 1000);
  
  self.postMessage({
    type: 'STARTED',
    message: 'Version checking started'
  });
}

// 停止版本检查
function stopVersionCheck() {
  if (checkInterval) {
    clearInterval(checkInterval);
    checkInterval = null;
  }
  
  self.postMessage({
    type: 'STOPPED',
    message: 'Version checking stopped'
  });
}

// 检查版本
async function checkVersion() {
  try {
    const response = await fetch(href + '?t=' + Date.now());
    if (!response.ok) {
      throw new Error("HTTP error! status: " + response.status);
    }
    
    const versionData = await response.json();
    const serverVersion = versionData.version;
    
    if (currentVersion && serverVersion !== currentVersion) {
      self.postMessage({
        type: 'VERSION_CHANGED',
        oldVersion: currentVersion,
        newVersion: serverVersion,
        message: "Version changed from " + currentVersion + " to " + serverVersion
      });
    } else {
      self.postMessage({
        type: 'VERSION_CHECK',
        version: serverVersion,
        message: 'Version check completed'
      });
    }
  } catch (error) {
    self.postMessage({
      type: 'ERROR',
      error: error.message,
      message: 'Failed to check version'
    });
  }
}
